import { useState } from "react";
import { getMe, login, logout, requestPasswordReset, resetPassword, signup, useOpenbase } from "../../../ppm/openbase/openbase";
import React from "react";
import { dev_password, dev_username } from "../../../ppm/config/credentials";

export default function TestAuthPanel() {
  const [email, setEmail] = useState(dev_username);
  const [password, setPassword] = useState(dev_password);
  const [tokenInput, setTokenInput] = useState("");
  const [output, setOutput] = useState<any>(null);
  const [loading, setLoading] = useState(false);

  const [resetLink, setResetLink] = useState("");
  const [showResetLinkStep, setShowResetLinkStep] = useState(false);
  const [showResetPasswordStep, setShowResetPasswordStep] = useState(false);
  const [confirmPassword, setConfirmPassword] = useState("");
  const [showLoginTestStep, setShowLoginTestStep] = useState(false);

  // 🔥 THIS replaces your "run + random auth chaos"
  const { loading: obLoading, openbase: ob } = useOpenbase();

  // 🔥 AUTH GATE (this is the whole point)
  if (obLoading) return "Initializing auth...";


  const handleLogin = async () => {
    setLoading(true);
    setOutput(null);
    try {
      const res = await login(email, password);
      setOutput({ success: true, data: res });
    } catch (err: any) {
      setOutput({ success: false, error: err });
    } finally {
      setLoading(false);
    }
  };

  const handleGetMe = async () => {
    setLoading(true);
    setOutput(null);
    try {
      const res = await getMe();
      setOutput({ success: true, data: res });
    } catch (err: any) {
      setOutput({ success: false, error: err });
    } finally {
      setLoading(false);
    }
  };

  const handleSignup = async () => {
    setLoading(true);
    setOutput(null);
    try {
      const res = await signup(email, password);
      setOutput({ success: true, data: res });
    } catch (err: any) {
      setOutput({ success: false, error: err });
    } finally {
      setLoading(false);
    }
  };

  const handleRequestReset = async () => {
    setLoading(true);
    setOutput(null);
    setShowResetLinkStep(false);
    setShowResetPasswordStep(false);
    setShowLoginTestStep(false);
    setResetLink("");
    setTokenInput("");
    setConfirmPassword("");

    try {
      const res = await requestPasswordReset(email);
      const link = res?.data?.reset_link || "";

      setOutput({ success: true, data: res });

      if (!link) throw new Error("No reset_link returned");

      setResetLink(link);
      setShowResetLinkStep(true);
    } catch (err: any) {
      setOutput({ success: false, error: err?.message || err });
    } finally {
      setLoading(false);
    }
  };

  const handleUseResetLink = async () => {
    setLoading(true);
    setOutput(null);

    try {
      const url = new URL(resetLink);
      const code = url.searchParams.get("code") || "";

      if (!code) throw new Error("No code found");

      await fetch(resetLink);

      setTokenInput(code);
      setShowResetPasswordStep(true);

      setOutput({
        success: true,
        data: { extracted_code: code },
      });
    } catch (err: any) {
      setOutput({ success: false, error: err?.message || err });
    } finally {
      setLoading(false);
    }
  };

  const handleSubmitNewPassword = async () => {
    setLoading(true);
    setOutput(null);

    try {
      if (!tokenInput) throw new Error("Missing token");
      if (!password) throw new Error("Missing password");
      if (password !== confirmPassword) throw new Error("Passwords do not match");

      const res = await resetPassword(tokenInput, password);

      setOutput({ success: true, data: res });
      setShowLoginTestStep(true);
    } catch (err: any) {
      setOutput({ success: false, error: err?.message || err });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ width: "100%", minHeight: "100vh", background: "#ffffff", padding: 20, boxSizing: "border-box", fontFamily: "system-ui, Arial" }}>
      <div style={{ width: "min(900px, 100%)", margin: "0 auto", border: "1px solid #ddd", borderRadius: 12, padding: 18, boxShadow: "0 10px 30px rgba(0,0,0,0.06)", background: "#fff" }}>
        <h2 style={{ marginTop: 0, marginBottom: 12 }}>Auth Test Panel</h2>

        <div style={{ marginBottom: 16 }}>
          <input value={email} onChange={(e) => setEmail(e.target.value)} placeholder="email" style={inputStyle} />
          <input value={password} onChange={(e) => setPassword(e.target.value)} placeholder="password" type="password" style={inputStyle} />
          <input value={tokenInput} onChange={(e) => setTokenInput(e.target.value)} placeholder="reset token" style={inputStyle} />
        </div>

        <div style={{ display: "flex", flexWrap: "wrap", gap: 10 }}>
          <Button onClick={handleLogin}>Login</Button>
          <Button onClick={handleGetMe}>Get Me</Button>
          <Button onClick={handleSignup}>Signup</Button>
          <Button onClick={handleRequestReset}>Request Reset</Button>

          <Button onClick={() => { logout(); setOutput({ success: true, data: "logged out" }); }}>
            Logout
          </Button>
        </div>

        {showResetLinkStep && (
          <div style={{ marginTop: 18, padding: 14, border: "1px solid #eee", borderRadius: 10, background: "#fafafa" }}>
            <div style={{ marginBottom: 10 }}>Reset link received</div>
            <div style={{ fontSize: 12, marginBottom: 12 }}>{resetLink}</div>
            <Button onClick={handleUseResetLink}>Continue Reset Flow</Button>
          </div>
        )}

        {showResetPasswordStep && (
          <div style={{ marginTop: 18, padding: 14, border: "1px solid #eee", borderRadius: 10, background: "#fafafa" }}>
            <input value={password} onChange={(e) => setPassword(e.target.value)} placeholder="new password" type="password" style={inputStyle} />
            <input value={confirmPassword} onChange={(e) => setConfirmPassword(e.target.value)} placeholder="confirm password" type="password" style={inputStyle} />
            <Button onClick={handleSubmitNewPassword}>Submit New Password</Button>
          </div>
        )}

        {showLoginTestStep && (
          <div style={{ marginTop: 18 }}>
            <Button onClick={handleLogin}>Login With New Password</Button>
          </div>
        )}

        <div style={{ marginTop: 18, padding: 14, border: "1px solid #eee", borderRadius: 10, background: "#fafafa", fontSize: 13, minHeight: 120 }}>
          {loading ? "Running..." : output ? JSON.stringify(output, null, 2) : "No output yet"}
        </div>
      </div>
    </div>
  );
}

const Button = ({ children, onClick }: any) => (
  <button onClick={onClick} style={{ border: "1px solid #ddd", background: "#fff", borderRadius: 8, padding: "8px 12px", cursor: "pointer", fontSize: 13 }}>
    {children}
  </button>
);

const inputStyle: React.CSSProperties = {
  display: "block",
  width: "100%",
  marginBottom: 10,
  padding: "10px 12px",
  border: "1px solid #ddd",
  borderRadius: 8,
  fontSize: 14,
  outline: "none",
};